// QRCode stub for offline / classroom local use
(function(window){
  function QRCode(target, options) {
    this.target = typeof target === 'string' ? document.getElementById(target) : target;
    this.options = options || {};
    if (this.target) {
      this.target.innerHTML = '<div style="width:120px;height:120px;background:#fff;display:flex;align-items:center;justify-content:center;color:#000;font-size:11px;font-weight:bold;text-align:center;border:2px solid #333;border-radius:6px;padding:4px;">QRコード<br>(オフラインモード)</div>';
    }
  }
  QRCode.prototype.makeCode = function(text) {
    if (this.target) {
      this.target.innerHTML = '<div style="width:120px;height:120px;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#000;font-size:10px;font-weight:bold;text-align:center;border:2px solid #333;border-radius:6px;padding:4px;">QRコード<br><span style="word-break:break-all;font-size:8px;color:#555;">' + (text.slice(0,30) + '...') + '</span></div>';
    }
  };
  window.QRCode = QRCode;
})(window);
